CREATE TABLE "tax_rule_sources" ("id" TEXT PRIMARY KEY, "title" VARCHAR(500) NOT NULL, "issuer" VARCHAR(255) NOT NULL, "officialUrl" VARCHAR(1000) NOT NULL, "jurisdiction" VARCHAR(100) NOT NULL, "originalStoragePath" VARCHAR(500) NOT NULL, "derivedMarkdownPath" VARCHAR(500), "contentHash" VARCHAR(64) NOT NULL, "reviewStatus" VARCHAR(20) NOT NULL DEFAULT 'draft', "reviewedBy" VARCHAR(255), "reviewedAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "tax_rule_sets" ("id" TEXT PRIMARY KEY, "version" INTEGER NOT NULL, "purpose" VARCHAR(50) NOT NULL, "taxRegime" VARCHAR(50) NOT NULL, "vatFilingFrequency" VARCHAR(20) NOT NULL, "effectiveFrom" DATE NOT NULL, "effectiveTo" DATE, "contentHash" VARCHAR(64) NOT NULL, "reviewStatus" VARCHAR(20) NOT NULL DEFAULT 'draft', "reviewedBy" VARCHAR(255), "reviewedAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "tax_ruleset_version_key" ON "tax_rule_sets"("purpose", "taxRegime", "vatFilingFrequency", "effectiveFrom", "version");
CREATE INDEX "tax_ruleset_selector_idx" ON "tax_rule_sets"("purpose", "taxRegime", "vatFilingFrequency", "reviewStatus");
CREATE TABLE "tax_rule_fragments" ("id" TEXT PRIMARY KEY, "sourceId" TEXT NOT NULL REFERENCES "tax_rule_sources"("id") ON DELETE RESTRICT, "articleOrSection" VARCHAR(255) NOT NULL, "contentHash" VARCHAR(64) NOT NULL, "contentMarkdown" TEXT NOT NULL, "purposes" TEXT[] NOT NULL, "taxRegimes" TEXT[] NOT NULL, "effectiveFrom" DATE NOT NULL, "effectiveTo" DATE);
CREATE TABLE "tax_rule_set_fragments" ("id" TEXT PRIMARY KEY, "ruleSetId" TEXT NOT NULL REFERENCES "tax_rule_sets"("id") ON DELETE CASCADE, "fragmentId" TEXT NOT NULL REFERENCES "tax_rule_fragments"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "tax_ruleset_fragment_unique" ON "tax_rule_set_fragments"("ruleSetId", "fragmentId");
